using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Service registration ----------------------------------------------------

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();
var chatClient = provider.GetRequiredService<IChatClient>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.WriteLine($"  🔍  Searching: {query}");
            return WebSearch.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information about a topic and returns relevant snippets. Use this to gather facts before summarizing."),

    AIFunctionFactory.Create(
        ([Description("A concise factual note to remember")] string note) =>
        {
            Console.WriteLine($"  📝  Noted: {note}");
            notebook.Add(note);
            return $"Note saved ({notebook.Count} total).";
        },
        "take_note",
        "Saves a key fact or finding for later reference. Use this to record important information discovered during research."),

    AIFunctionFactory.Create(
        () =>
        {
            Console.WriteLine("  📖  Reading notes...");
            return notebook.Count == 0
                ? "No notes yet."
                : string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}"));
        },
        "read_notes",
        "Retrieves all notes taken so far. Use this before writing a summary to review collected facts."),
};

// --- Agent -------------------------------------------------------------------

const string instructions = """
    You are a research assistant. When given a topic:
    1. Search the web multiple times with varied queries to gather diverse information.
    2. Take notes on the most important facts, statistics, and insights you find.
    3. Read your notes and synthesize them into a well-structured summary.
    4. Present the final summary to the user with key findings and sources.
    Be thorough — perform at least 3 searches before summarizing.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches topics using web search and note-taking",
    tools: tools,
    loggerFactory: loggerFactory);

// --- Run ---------------------------------------------------------------------

Console.WriteLine("🔬 Research Agent");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();
    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();

    var runOptions = new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    });

    await foreach (var update in agent.RunStreamingAsync(
        $"Research the following topic and provide a comprehensive summary: {topic}",
        session,
        runOptions))
    {
        Console.Write(update.Text);
    }

    Console.WriteLine("\n");
}

// --- Supporting types --------------------------------------------------------

/// <summary>Simple in-memory notebook for the agent's note-taking tool.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;
    public int Count => _notes.Count;
    public void Add(string note) => _notes.Add(note);
    public void Clear() => _notes.Clear();
}

/// <summary>Simulated web search returning canned results for demonstration.</summary>
static class WebSearch
{
    public static Task<string> SearchAsync(string query)
    {
        var q = query.ToLowerInvariant();

        // Return plausible simulated results so the agent can work without a real API.
        var results = new List<string>();

        if (q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("ai"))
        {
            results.AddRange([
                "According to Stanford's 2024 AI Index, global AI investment reached $189 billion in 2023.",
                "Generative AI models like GPT-4 and Gemini have demonstrated human-level performance on many benchmarks.",
                "The EU AI Act, passed in 2024, is the world's first comprehensive AI regulation framework.",
            ]);
        }

        if (q.Contains("climate") || q.Contains("warming") || q.Contains("environment"))
        {
            results.AddRange([
                "NASA reports 2024 was the hottest year on record, with global temperatures 1.5°C above pre-industrial levels.",
                "Renewable energy capacity grew by 50% in 2023, led by solar power installations in China.",
                "The IPCC's latest report warns that limiting warming to 1.5°C requires cutting emissions by 43% by 2030.",
            ]);
        }

        if (q.Contains("quantum") || q.Contains("computing"))
        {
            results.AddRange([
                "Google's Willow chip achieved quantum error correction below the threshold, a major milestone.",
                "IBM plans to deliver a 100,000-qubit system by 2033 through modular quantum architectures.",
                "Quantum computing market is projected to reach $65 billion by 2030 (McKinsey).",
            ]);
        }

        if (q.Contains("space") || q.Contains("mars") || q.Contains("nasa"))
        {
            results.AddRange([
                "SpaceX's Starship completed its first successful orbital test flight in 2024.",
                "NASA's Artemis program aims to return humans to the Moon by 2026.",
                "The James Webb Space Telescope has discovered galaxies formed just 300 million years after the Big Bang.",
            ]);
        }

        if (results.Count == 0)
        {
            results.AddRange([
                $"'{query}' is an active area of research with growing interest from academia and industry.",
                $"Recent studies on '{query}' suggest significant developments are expected in the coming years.",
                $"Experts in '{query}' highlight both opportunities and challenges that need to be addressed.",
            ]);
        }

        return Task.FromResult(string.Join("\n", results.Select((r, i) => $"[{i + 1}] {r}")));
    }
}

